const problemDescription = `PROBLEM: User selects 11000+ small CSV files on the Upload page (mobile browser). After selection, screen goes black and app becomes unresponsive. The file list never appears. Mobile browser kills the tab.

ANALYSIS FROM CLAUDE AI:
1. Dedup might be O(n^2) - but checking the code, it uses Set so it's O(n)
2. Multiple full-array passes over 11000 items
3. setState called per-file instead of once
4. No yielding back to the event loop - main thread blocks, mobile watchdog kills tab

CURRENT STATE: addFiles was made async with chunked processing (500 per chunk with setTimeout yield), but problem still occurs.

QUESTIONS:
- Is the chunked yield approach correct? Why might it still fail?
- Could the issue be in the browser's native file picker itself handling 11000+ files?
- Could App.tsx keeping UploadPage always mounted (with hidden class) contribute?
- Is there a memory issue with storing 11000 File objects in a ref?
- Could StrictMode double-rendering cause issues?
- Should we use a Web Worker instead?
`;

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 200, headers: corsHeaders });
  }

  const url = new URL(req.url);
  
  if (url.pathname.endsWith("/raw")) {
    let output = "=== PROBLEM DESCRIPTION ===\n\n";
    output += problemDescription;
    output += "\n\n=== SOURCE CODE ===\n\n";
    const files = JSON.parse(sourceFiles);
    for (const [name, content] of Object.entries(files)) {
      output += "\n--- FILE: " + name + " ---\n\n";
      output += content;
      output += "\n";
    }
    return new Response(output, {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "text/plain; charset=utf-8" },
    });
  }

  const files = JSON.parse(sourceFiles);
  return new Response(JSON.stringify({
    problem: problemDescription,
    files: files,
    fileCount: Object.keys(files).length,
  }, null, 2), {
    status: 200,
    headers: { ...corsHeaders, "Content-Type": "application/json; charset=utf-8" },
  });
});
